//! Original LX7 MMIO diagnostics; no factory firmware/hardware acceptance claim.
use emu_core::{Bus,Core};
use esp_soc::{SocBus,Stop,picture::{Picture,Jpeg,JpegError}};
const PC:u32=0x40370000;const GPIO:u32=0x60004000;const LCD:u32=0x60041000;const DESC:u32=0x3fc88000;const DATA:u32=0x3fc90000;const PERIOD:u64=24_000_000;
struct Guest {m:esp32s3::Machine,five:bool}
impl Guest {
    fn new(five:bool)->Self {let mut m=esp32s3::machine([0;6]);m.bus.board=esp32s3::board::make_board(if five{"unit-cams3-5mp"}else{"unit-cams3"}).unwrap();m.bus.attach_board_devices();m.bus.set_flash_size(16<<20);m.bus.set_psram_size(8<<20).unwrap();let mut g=Self{m,five};g.program();g}
    fn program(&mut self){self.m.bus.load_bytes(PC,&[0x32,0x64,0,0x52,0x24,0]).unwrap();self.m.cores[0].ps=0;self.m.cores[0].set_jit(false);}
    fn put(&mut self,a:u32,v:u32){self.m.cores[0].pc=PC;self.m.cores[0].set_ar(4,a);self.m.cores[0].set_ar(3,v);assert!(matches!(self.m.run(1),Stop::MaxInsns));}
    fn get(&mut self,a:u32)->u32{self.m.cores[0].pc=PC+3;self.m.cores[0].set_ar(4,a);assert!(matches!(self.m.run(1),Stop::MaxInsns));self.m.cores[0].get_ar(5)}
    fn route(&mut self,p:u8,s:u32){self.put(0x60009004+4*u32::from(p),1<<12|1<<9);self.put(GPIO+0x554+4*u32::from(p),s);if s==256{self.put(GPIO+if p<32{0x24}else{0x30},1<<(p%32));}}
    fn high(&mut self,p:u8,v:bool){self.put(GPIO+if p<32{if v{8}else{12}}else if v{20}else{24},1<<(p%32));}
    fn i2c_route(&mut self,b:u32,sda:u8,scl:u8){for(p,s)in[(sda,90+b*2),(scl,89+b*2)]{self.route(p,s);self.put(GPIO+0x154+4*s,0x80|u32::from(p));}}
    fn i2c(&mut self,b:usize,a:u8,bytes:&[u8],n:u8)->Option<Vec<u8>>{let base=[0x60013000,0x60027000][b];self.put(base+0x24,u32::MAX);self.put(base+0x18,3<<12);for v in[a<<1].into_iter().chain(bytes.iter().copied()){self.put(base+0x1c,u32::from(v));}let mut cmd=vec![6<<11,1<<11|1<<8|(bytes.len()+1)as u32];if n>0{self.put(base+0x1c,u32::from(a<<1|1));cmd.extend([6<<11,1<<11|1<<8|1,3<<11|u32::from(n)]);}cmd.push(2<<11);for(i,v)in cmd.into_iter().enumerate(){self.put(base+0x58+4*i as u32,v);}self.put(base+4,1<<5);self.m.bus.tick(100_000);if self.get(base+0x20)&(1<<10)!=0{return None;}assert_ne!(self.get(base+0x20)&(1<<7),0);Some((0..n).map(|_|self.get(base+0x1c)as u8).collect())}
    fn wr(&mut self,r:u16,v:u8){let bytes=if self.five{vec![(r>>8)as u8,r as u8,v]}else{vec![r as u8,v]};let a=if self.five{0x1f}else{0x30};assert_eq!(self.i2c(0,a,&bytes,0),Some(vec![]));}
    fn configure(&mut self,jpeg:bool){self.i2c_route(0,17,41);if self.five{self.wr(0x121,7);self.wr(0x120,if jpeg{1}else{0x10});}else{for(r,v)in[(0xff,0),(0x5a,2),(0x5b,1),(0x5c,0),(0xda,if jpeg{0x12}else{8})]{self.wr(r,v);}}}
    fn dvp(&mut self){for(i,p)in[6,15,16,7,5,10,4,13,12,18,42].into_iter().enumerate(){self.route(p,256);self.put(GPIO+if p<32{0x28}else{0x34},1<<(p%32));let s=if i<8{133+i as u32}else{[149,150,152][i-8]};self.put(GPIO+0x154+4*s,0x80|u32::from(p));}self.route(11,149);self.put(0x600c001c,1<<8);self.put(LCD+4,3<<29|8<<9);self.put(LCD+0x64,1<<2);}
    fn frame(&mut self,len:usize,owned:bool)->Vec<u8>{self.put(LCD+8,0);self.put(LCD+0x70,u32::MAX);self.put(0x6003f020,1<<21);self.put(0x6003f014,u32::MAX);self.m.bus.load_bytes(DATA,&vec![0xa5;len+4]).unwrap();let mut at=0;let mut index=0;while at<len{let count=(len-at).min(4092);let next=if at+count==len{0}else{DESC+12*(index+1)};for(i,v)in[(u32::from(owned)<<31)|count as u32,DATA+at as u32,next].into_iter().enumerate(){self.put(DESC+12*index+4*i as u32,v);}at+=count;index+=1;}self.put(0x6003f004,1<<12);self.put(0x6003f048,5);self.put(0x6003f020,(DESC&0xfffff)|(1<<22));self.put(LCD+8,(1<<29)|(len as u32-1));self.m.bus.tick((PERIOD-self.m.bus.periph.lcd_cam.acc)as u32);self.m.bus.tick((PERIOD*11/20)as u32);(0..len).map(|i|self.m.bus.read8(DATA+i as u32).unwrap()).collect()}
}
#[test]
fn exact_sccb_identity_controllers_reset_and_wrong_bus(){for five in[false,true]{let mut g=Guest::new(five);let a=if five{0x1f}else{0x30};let reg=if five{vec![0,0]}else{vec![0x0a]};g.i2c_route(0,41,17);assert_eq!(g.i2c(0,a,&reg,1),None);g.i2c_route(0,17,41);assert_eq!(g.i2c(0,a,&reg,1),Some(vec![if five{3}else{0x26}]));assert_eq!(g.i2c(0,if five{0x30}else{0x1f},&reg,1),None);g.i2c_route(1,17,41);assert_eq!(g.i2c(1,a,&reg,1),Some(vec![if five{3}else{0x26}]));g.route(21,256);g.high(21,false);assert_eq!(g.i2c(1,a,&reg,1),None);g.high(21,true);assert_eq!(g.i2c(1,a,&reg,1),Some(vec![if five{3}else{0x26}]));g.route(14,256);g.high(14,false);assert_eq!(g.m.bus.board.leds().unwrap().0,[[0,0,255]]);g.high(14,true);assert_eq!(g.m.bus.board.leds().unwrap().0,[[0;3]]);}}
#[test]
fn explicit_picture_reaches_guest_dma_and_routes_clock_owner_are_required(){for five in[false,true]{let mut g=Guest::new(five);g.configure(false);g.m.bus.board.set_camera_picture(Picture{w:2,h:1,rgb:vec![255,0,0,0,255,0]}).unwrap();g.dvp();let(w,h)=if five{(96,96)}else{(8,4)};let len=w*h*2;let expected:Vec<u8>=(0..h).flat_map(|_|(0..w).flat_map(|x|if x<w/2{[248,0]}else{[7,224]})).collect();assert_eq!(g.frame(len,true),expected);assert_eq!(g.get(DESC)>>31,0);assert_ne!(g.get(0x6003f008)&3,0);
    g.put(GPIO+0x154+4*133,0x80|15);assert_eq!(g.frame(len,true),vec![0xa5;len]);g.put(GPIO+0x154+4*133,0x80|6);g.route(11,256);assert_eq!(g.frame(len,true),vec![0xa5;len]);g.route(11,149);assert_eq!(g.frame(len,false),vec![0xa5;len]);assert_ne!(g.get(0x6003f008)&(1<<3),0);g.put(LCD+4,0);assert_eq!(g.frame(len,true),vec![0xa5;len]);g.put(LCD+4,3<<29|8<<9);assert_eq!(g.frame(len,true),expected);
    g.route(21,256);g.high(21,false);assert_eq!(g.frame(len,true),vec![0xa5;len]);g.high(21,true);assert_eq!(g.frame(len,true),vec![0xa5;len]);g.configure(false);assert_eq!(g.frame(len,true),expected);g.m.reboot();g.program();assert!(g.m.bus.board.camera_preview(2,1).is_some());assert_eq!(g.m.bus.periph.lcd_cam.frames,0);g.dvp();assert_eq!(g.frame(len,true),vec![0xa5;len]);}}
#[test]
fn encoded_jpeg_is_verbatim_and_never_raw_fallback(){for five in[false,true]{let mut g=Guest::new(five);g.configure(true);g.dvp();assert_eq!(g.frame(32,true),vec![0xa5;32]);let(w,h)=if five{(96,96)}else{(8,4)};let bytes=vec![255,216,255,192,0,11,8,0,h,0,w,1,1,0x11,0,255,218,0,8,1,1,0,0,63,0,0x42,255,0,0x23,255,217];let jpeg=Jpeg::parse(bytes.clone()).unwrap();g.m.bus.board.set_camera_jpeg(jpeg).unwrap();assert_eq!(g.frame(bytes.len(),true),bytes);assert_eq!(g.m.bus.read8(DATA+bytes.len()as u32).unwrap(),0xa5);assert!(matches!(g.m.bus.board.set_camera_jpeg(Jpeg{w:1,h:1,bytes:std::sync::Arc::new(vec![])}),Err(JpegError::SizeMismatch{..})));assert_eq!(g.frame(bytes.len(),true),bytes);}}

impl Guest {
    fn spi(&mut self,bytes:&[u8])->Vec<u8>{let mut out=Vec::new();for chunk in bytes.chunks(64){for(i,w)in chunk.chunks(4).enumerate(){let mut data=[0;4];data[..w.len()].copy_from_slice(w);self.put(0x60024098+4*i as u32,u32::from_le_bytes(data));}self.put(0x60024010,1<<27|1<<28);self.put(0x6002401c,(chunk.len()*8-1)as u32);self.put(0x60024000,1<<24);out.extend((0..chunk.len()).map(|i|((self.get(0x60024098+4*(i/4)as u32)>>((i%4)*8))&255)as u8));}out}
    fn sd_cmd(&mut self,c:u8,arg:u32)->Vec<u8>{let mut bytes=vec![0x40|c];bytes.extend(arg.to_be_bytes());let mut crc=0u8;for &v in &bytes{let mut b=v;for _ in 0..8{crc<<=1;if(b^crc)&0x80!=0{crc^=9;}b<<=1;}}bytes.push((crc&0x7f)<<1|1);self.spi(&bytes);self.spi(&[255;2])}
    fn sd_init(&mut self){self.route(9,256);self.high(9,true);self.spi(&[255;10]);self.high(9,false);assert_eq!(self.sd_cmd(0,0),[255,1]);assert_eq!(self.sd_cmd(8,0x1aa),[255,1]);assert_eq!(self.spi(&[255;4]),[0,0,1,0xaa]);for _ in 0..2{self.sd_cmd(55,0);self.sd_cmd(41,1<<30);}}
    fn sd_read(&mut self)->Vec<u8>{assert_eq!(self.sd_cmd(17,3),[255,0]);assert_eq!(self.spi(&[255;2]),[255,0xfe]);let out=self.spi(&[255;512]);self.spi(&[255;2]);out}
}
#[test]
fn both_exact_spi_tf_slots_roundtrip_guest_blocks_and_reject_wrong_wire_and_eject(){for five in[false,true]{let mut g=Guest::new(five);g.m.bus.attach_sd_card(Box::new(esp_periph::sdmmc::MemStore(vec![0;1<<20])),Default::default()).unwrap();for(p,s)in[(39,101),(38,103),(40,256)]{g.route(p,s);}g.put(GPIO+0x34,1<<(40-32));g.put(GPIO+0x154+4*102,0x80|40);g.put(0x60024020,0x3f);g.sd_init();assert_eq!(g.sd_cmd(24,3),[255,0]);let mut data=vec![0xfe];data.extend((0..512).map(|i|(i%251)as u8));data.extend([255;2]);g.spi(&data);assert_eq!(g.spi(&[255]),[5]);assert_eq!(g.sd_read(),data[1..513]);g.put(GPIO+0x154+4*102,0x80|41);assert_eq!(g.sd_cmd(58,0),[255;2]);g.put(GPIO+0x154+4*102,0x80|40);g.m.bus.board.set_sd_card_present(false);assert_eq!(g.sd_cmd(0,0),[255;2]);g.m.bus.board.set_sd_card_present(true);g.sd_init();assert_eq!(g.sd_read(),data[1..513]);}}
